mapper.select:
SELECT dc.*, IFNULL( cab.cabinetNum, 0 ) AS cabinetNum, IFNULL( asset.assetNum, 0 ) AS assetNum, IFNULL( msg.alertNum, 0 ) AS alertNum, IFNULL( sta.starred, 0 ) AS starred FROM dc dc LEFT JOIN ( SELECT dc_id, count( 1 ) cabinetNum FROM cabinet GROUP BY dc_id ) cab ON cab.dc_id = dc.id LEFT JOIN ( SELECT dc_id, count( 1 ) assetNum FROM asset_asset GROUP BY dc_id ) asset ON asset.dc_id = dc.id LEFT JOIN ( SELECT dc_id, count( 1 ) alertNum FROM alert_message_active WHERE dc_id IS NOT NULL GROUP BY dc_id ) msg ON dc.id = msg.dc_id LEFT JOIN ( SELECT IF(COUNT(1) > 0, 1, 0) AS starred,tid FROM sys_user_starred WHERE TYPE = "datacenter" AND uid = #{params.currentLoginUserID} GROUP BY tid) sta ON dc.id = sta.tid
dc.id in
#{id}
AND locate(#{params.name} , dc.name)
AND locate(#{params.location} , dc.location)
AND locate(#{params.tel} , dc.tel)
AND locate(#{params.state} , dc.state)
AND dc.principal = #{params.principal}
AND IFNULL( sta.starred, 0 ) = #{params.starred}
ORDER BY dc.id
